import { getAllProducts } from '@/lib/db';
import { revalidateTag, unstable_cache } from 'next/cache';

const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['products-list'],
  { tags: ['products'] }
);

export default async function Page() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Product Catalog</h1>
      <div style={{ marginBottom: '1rem', padding: '1rem', border: '1px solid #ccc' }}>
        <p><strong>Catalog Status</strong></p>
        <p>Last Refreshed: {products[0]?.lastUpdated || 'Unknown'}</p>

        <form action={syncCatalog}>
          <button 
            type="submit" 
            style={{ 
              padding: '0.5rem 1rem', 
              background: '#0070f3', 
              color: 'white', 
              border: 'none', 
              borderRadius: '4px',
              cursor: 'pointer' 
            }}
          >
            Sync latest catalog
          </button>
        </form>
        <p style={{ fontSize: '0.8rem', color: '#666', marginTop: '0.5rem' }}>
          Triggers a background refresh. Data will update shortly.
        </p>
      </div>

      <ul>
        {products.map(product => (
          <li key={product.id} style={{ padding: '0.5rem 0', borderBottom: '1px solid #eee' }}>
            <strong>{product.name}</strong> - ${product.price}
          </li>
        ))}
      </ul>
    </main>
  );
}

